119: fn find_eocd(b: &[u8]) -> Option<usize> {
120:     if b.len() < 22 {
121:         return None;
122:     }
123:     let start = b.len().saturating_sub(66_000);
124:     (start..=b.len() - 22).rev().find(|&i| b[i..i + 4] == [0x50, 0x4b, 0x05, 0x06])
125: }
