204: fn decode(data: &[u8], name: &str, password: Option<&str>) -> R<Vec<u8>> {
205:     let (s, e, method, crc, dostime, enc, usize_) = data_range(data, name)?;
206:     let mut raw = data.get(s..e).ok_or(ZipError::NotZip)?.to_vec();
207:     if enc {
208:         let pw = password.ok_or(ZipError::PasswordRequired)?;
209:         let mut c = Crypto::new(pw);
210:         c.decrypt(&mut raw);
211:         if raw.len() < 12 {
212:             return Err(ZipError::BadPassword);
213:         }
214:         let check = raw[11];
215:         let want = (crc >> 24) as u8;
216:         let want2 = (dostime >> 8) as u8;
217:         if check != want && check != want2 {
218:             return Err(ZipError::BadPassword);
219:         }
220:         raw.drain(0..12);
221:     }
222:     let out = match method {
223:         0 => raw,
224:         8 => miniz_oxide::inflate::decompress_to_vec(&raw).map_err(|_| ZipError::Unsupported("corrupt deflate stream".into()))?,
225:         m => return Err(ZipError::Unsupported(format!("method {m}"))),
226:     };
227:     if !out.is_empty() && crc32(&out) != crc {
228:         return Err(ZipError::Unsupported("checksum mismatch".into()));
229:     }
230:     let _ = usize_;
231:     Ok(out)
232: }
