238: fn safe_join(dest: &Location, name: &str) -> Option<Location> {
239:     let clean: Vec<&str> = name.split('/').filter(|s| !s.is_empty() && *s != ".").collect();
240:     if clean.iter().any(|s| *s == "..") || clean.is_empty() {
241:         return None;
242:     }
243:     Some(dest.join(&clean.join("/")))
244: }
