250: /// Extract every entry into `dest` (creating folders). Returns (files, bytes).
251: pub fn extract(reg: &Registry, src: &Location, dest: &Location, password: Option<&str>, mut progress: impl FnMut(&str, u64, u64)) -> R<(usize, u64)> {
252:     let sv = reg.get(&src.fs).ok_or_else(|| ZipError::Io("missing file system".into()))?;
253:     let dv = reg.get(&dest.fs).ok_or_else(|| ZipError::Io("missing file system".into()))?;
254:     let bytes = read_archive(sv.as_ref(), src)?;
255:     let entries = list(&bytes, password)?;
256:     let size_total: u64 = entries.iter().filter(|e| !e.is_dir).map(|e| e.size).sum();
257:     // Data-descriptor zips report 0 sizes in the central dir — fall back to per-file steps
258:     // so the progress bar always moves.
259:     let by_count = size_total == 0;
260:     let total = if by_count { entries.iter().filter(|e| !e.is_dir).count() as u64 } else { size_total };
261:     let mut done = 0u64;
262:     let mut files = 0usize;
263:     for e in &entries {
264:         let Some(target) = safe_join(dest, &e.name) else { continue };
265:         if e.is_dir {
266:             let _ = dv.mkdir(&target.path);
267:             continue;
268:         }
269:         let data = decode(&bytes, &e.name, password)?;
270:         if let Some(parent) = e.name.rsplit_once('/').map(|(p, _)| p) {
271:             let mut cur = dest.clone();
272:             for seg in parent.split('/').filter(|s| !s.is_empty()) {
273:                 cur = cur.join(seg);
274:                 let _ = dv.mkdir(&cur.path);
275:             }
276:         }
277:         dv.write(&target.path, &data).map_err(|x| ZipError::Io(x.to_string()))?;
278:         done += if by_count { 1 } else { e.size };
279:         files += 1;
280:         progress(&e.name, done, total.max(1));
281:     }
282:     Ok((files, done))
283: }
