443:     #[test]
444:     fn roundtrip_and_password() {
445:         let reg = Registry::new();
446:         let v = Arc::new(MemVfs::new("mem"));
447:         reg.insert(v.clone());
448:         v.put("/a.txt", b"hello world hello world hello world".to_vec(), None, 0);
449:         v.mkdir_p("/sub", 0);
450:         v.put("/sub/b.txt", vec![7u8; 5000], None, 0);
451:         let out = Location::mem("/out.zip");
452:         compress(&reg, &[Location::mem("/a.txt"), Location::mem("/sub")], &out, Some("s3cret".into()), 6, |_, _, _| {}).unwrap();
453:         let entries = preview_entries(&reg, &out, Some("s3cret")).unwrap();
454:         assert!(entries.iter().any(|e| e.name == "a.txt" && e.encrypted));
455:         assert!(entries.iter().any(|e| e.name == "sub/b.txt"), "got {:?}", entries);
456:         let dest = Location::mem("/x");
457:         v.mkdir_p("/x", 0);
458:         let r = extract(&reg, &out, &dest, Some("s3cret"), |_, _, _| {});
459:         assert!(r.is_ok(), "{:?}", r.err());
