288: /// Natural, case-insensitive comparison ("img2" < "img10").
289: pub fn natural_cmp(a: &str, b: &str) -> std::cmp::Ordering {
290:     let (mut ai, mut bi) = (a.chars().peekable(), b.chars().peekable());
291:     loop {
292:         match (ai.peek().copied(), bi.peek().copied()) {
293:             (None, None) => return std::cmp::Ordering::Equal,
294:             (None, _) => return std::cmp::Ordering::Less,
295:             (_, None) => return std::cmp::Ordering::Greater,
296:             (Some(x), Some(y)) if x.is_ascii_digit() && y.is_ascii_digit() => {
297:                 let mut na = String::new();
298:                 let mut nb = String::new();
299:                 while let Some(c) = ai.peek().copied().filter(|c| c.is_ascii_digit()) {
300:                     na.push(c);
301:                     ai.next();
302:                 }
303:                 while let Some(c) = bi.peek().copied().filter(|c| c.is_ascii_digit()) {
304:                     nb.push(c);
305:                     bi.next();
306:                 }
307:                 let (na, nb) = (na.trim_start_matches('0'), nb.trim_start_matches('0'));
308:                 let o = na.len().cmp(&nb.len()).then_with(|| na.cmp(nb));
309:                 if o != std::cmp::Ordering::Equal {
310:                     return o;
311:                 }
312:             }
313:             (Some(x), Some(y)) => {
314:                 let o = x.to_lowercase().cmp(y.to_lowercase());
315:                 if o != std::cmp::Ordering::Equal {
316:                     return o;
317:                 }
318:                 ai.next();
319:                 bi.next();
320:             }
321:         }
322:     }
323: }
