328:             return b.is_dir.cmp(&a.is_dir);
329:         }
330:         let o = match key {
331:             SortKey::Name => natural_cmp(&a.name, &b.name),
332:             SortKey::Modified => b.modified.cmp(&a.modified).then_with(|| natural_cmp(&a.name, &b.name)),
333:             SortKey::Size => b.size.cmp(&a.size).then_with(|| natural_cmp(&a.name, &b.name)),
334:             SortKey::Kind => a.kind_label().cmp(&b.kind_label()).then_with(|| natural_cmp(&a.name, &b.name)),
