37: fn parse_size(s: &str) -> Option<u64> {
38:     let s = s.to_lowercase();
39:     let idx = s.find(|c: char| !(c.is_ascii_digit() || c == '.')).unwrap_or(s.len());
40:     let n: f64 = s[..idx].parse().ok()?;
41:     let mul = match s[idx..].trim() {
42:         "" | "b" => 1.0,
43:         "k" | "kb" => 1e3,
44:         "m" | "mb" => 1e6,
45:         "g" | "gb" => 1e9,
46:         "t" | "tb" => 1e12,
47:         _ => return None,
48:     };
49:     Some((n * mul) as u64)
50: }
