207:     pub fn watch(&mut self, loc: &Location) {
208:         use notify::{RecursiveMode, Watcher};
209:         self.watcher = None;
210:         let Some(path) = self.registry.get(&loc.fs).and_then(|v| v.real_path(&loc.path)) else { return };
211:         let (tx, l) = (self.tx.clone(), loc.clone());
212:         if let Ok(mut w) = notify::recommended_watcher(move |r: notify::Result<notify::Event>| {
213:             if r.is_ok() {
214:                 let _ = tx.send(Event::Changed(l.clone()));
215:             }
216:         }) {
217:             if w.watch(&path, RecursiveMode::NonRecursive).is_ok() {
218:                 self.watcher = Some(w);
219:             }
220:         }
221:     }
