250:     pub fn create_folder(&self, dir: &Location, name: &str) -> Result<Location, String> {
251:         let v = self.vfs(dir)?;
252:         let n = ops::unique_name(v.as_ref(), dir, name, None);
253:         let l = dir.join(&n);
254:         v.mkdir(&l.path).map_err(|e| e.to_string())?;
255:         self.search.invalidate(dir);
256:         Ok(l)
257:     }
258:     pub fn create_file(&self, dir: &Location, name: &str) -> Result<Location, String> {
259:         let v = self.vfs(dir)?;
260:         let n = ops::unique_name(v.as_ref(), dir, name, None);
261:         let l = dir.join(&n);
262:         v.write(&l.path, b"").map_err(|e| e.to_string())?;
263:         self.search.invalidate(dir);
264:         Ok(l)
265:     }
266:     pub fn rename(&self, loc: &Location, new_name: &str) -> Result<Location, String> {
267:         let name = new_name.trim();
268:         if name.is_empty() || name.contains('/') {
269:             return Err("That name isn\u{2019}t valid".into());
270:         }
271:         let Some(parent) = loc.parent() else { return Err("Can\u{2019}t rename this location".into()) };
272:         let to = parent.join(name);
273:         if to == *loc {
274:             return Ok(to);
275:         }
276:         self.vfs(loc)?.rename(&loc.path, &to.path).map_err(|e| match e {
277:             FsError::Exists => format!("\u{201c}{}\u{201d} already exists here", name),
278:             e => e.to_string(),
279:         })?;
280:         self.library.write().unwrap().rekey(loc, &to);
281:         self.search.invalidate(&parent);
282:         Ok(to)
283:     }
284:     pub fn read_bytes(&self, loc: &Location, limit: usize) -> Result<Vec<u8>, String> {
285:         self.vfs(loc)?.read(&loc.path, limit).map_err(|e| e.to_string())
286:     }
287:     pub fn read_text(&self, loc: &Location, limit: usize) -> Result<String, String> {
288:         let b = self.read_bytes(loc, limit)?;
289:         if b.iter().take(2048).any(|c| *c == 0) {
290:             return Err("Binary file".into());
291:         }
292:         Ok(String::from_utf8_lossy(&b).to_string())
293:     }
294:     pub fn write_text(&self, loc: &Location, text: &str) -> Result<(), String> {
295:         self.vfs(loc)?.write(&loc.path, text.as_bytes()).map_err(|e| e.to_string())
296:     }
