298:     // ───────── jobs ─────────
299:     pub fn submit(&self, kind: JobKind) -> u64 {
300:         let id = self.id();
301:         let cancel = Arc::new(AtomicBool::new(false));
302:         self.jobs.lock().unwrap().insert(id, cancel.clone());
303:         let (reg, tx) = (self.registry.clone(), self.tx.clone());
304:         spawn(move || {
305:             let tx2 = tx.clone();
306:             let ctx = JobCtx { id, cancel, emit: Box::new(move |e| { let _ = tx2.send(Event::Job(e)); }) };
307:             ops::run(&reg, kind, &ctx);
308:         });
309:         id
310:     }
311:     /// Does this job involve the demo “virtual” files? Those get a paced transfer animation.
312:     pub fn has_paced_sources(&self, kind: &JobKind) -> bool {
313:         kind.srcs().iter().take(8).any(|l| self.registry.get(&l.fs).and_then(|v| v.stat(&l.path).ok()).is_some_and(|e| e.paced))
314:     }
