316:     /// Copy/move with a deliberate, visible transfer (seconds of progress) — used for the 5 GB showcase files.
317:     pub fn submit_paced(&self, kind: JobKind, secs: f32) -> u64 {
318:         let id = self.id();
319:         let title = kind.title();
320:         let _ = self.tx.send(Event::Job(JobEvent::Started { id, title }));
321:         self.paced.lock().unwrap().push(PacedJob { id, kind, started_ms: crate::exec::now_millis(), secs: secs.clamp(0.2, 60.0), last: 0 });
322:         id
323:     }
