338:     /// Extract on a worker thread with real progress; refreshes the viewer when finished.
339:     pub fn archive_extract(&self, src: &Location, dest: &Location, password: Option<String>) {
340:         let (reg, tx, src, dest, id) = (self.registry.clone(), self.tx.clone(), src.clone(), dest.clone(), self.id());
341:         let title = format!("Extracting {}", src.name());
342:         let _ = tx.send(Event::Job(JobEvent::Started { id, title: title.clone() }));
343:         spawn(move || {
344:             let tx2 = tx.clone();
345:             let mut r = crate::archive::extract(&reg, &src, &dest, password.as_deref(), |name, done, total| {
346:                 let _ = tx2.send(Event::Job(JobEvent::Progress { id, done, total, current: name.to_string() }));
347:             });
348:             #[cfg(not(target_arch = "wasm32"))]
349:             if r.is_err() {
350:                 let sreal = reg.get(&src.fs).and_then(|v| v.real_path(&src.path));
351:                 let dreal = reg.get(&dest.fs).and_then(|v| v.real_path(&dest.path));
352:                 if let (Some(sr), Some(dr)) = (sreal, dreal) {
353:                     let hint = crate::archive::cli_list(sr.as_ref()).map(|e| e.len() as u64).unwrap_or(0);
354:                     let tx3 = tx2.clone();
355:                     if let Some(rr) = crate::archive::cli_extract(sr.as_ref(), dr.as_ref(), hint, move |name, done, total| {
356:                         let _ = tx3.send(Event::Job(JobEvent::Progress { id, done, total, current: name.to_string() }));
357:                     }) {
358:                         r = rr;
359:                     }
360:                 }
361:             }
362:             match r {
363:                 Ok((n, bytes)) => {
364:                     let _ = tx.send(Event::Job(JobEvent::Finished { id, created: vec![dest.clone()], touched: vec![dest.clone()] }));
365:                     let _ = tx.send(Event::Message { text: format!("Extracted {} files ({}) into {}", n, crate::model::format_size(bytes), dest.name()), ok: true });
366:                     let _ = tx.send(Event::ArchiveDone { loc: src, ok: true, detail: format!("{} files", n) });
367:                 }
368:                 Err(e) => {
369:                     let _ = tx.send(Event::Job(JobEvent::Failed { id, error: e.to_string() }));
370:                 }
371:             }
372:         });
373:     }
