375:     pub fn archive_compress(&self, srcs: Vec<Location>, dest_zip: Location, password: Option<String>, level: u8) {
376:         let (reg, tx, id) = (self.registry.clone(), self.tx.clone(), self.id());
377:         let title = format!("Creating {}", dest_zip.name());
378:         let _ = tx.send(Event::Job(JobEvent::Started { id, title }));
379:         spawn(move || {
380:             let tx2 = tx.clone();
381:             let r = crate::archive::compress(&reg, &srcs, &dest_zip, password, level, |name, done, total| {
382:                 let _ = tx2.send(Event::Job(JobEvent::Progress { id, done, total, current: name.to_string() }));
383:             });
384:             match r {
385:                 Ok((n, _)) => {
386:                     let parent = dest_zip.parent().unwrap_or_else(|| dest_zip.clone());
387:                     let _ = tx.send(Event::Job(JobEvent::Finished { id, created: vec![dest_zip.clone()], touched: vec![parent] }));
388:                     let _ = tx.send(Event::Message { text: format!("Compressed {} files into {}", n, dest_zip.name()), ok: true });
389:                     let _ = tx.send(Event::ArchiveDone { loc: dest_zip, ok: true, detail: format!("{} files", n) });
390:                 }
391:                 Err(e) => {
392:                     let _ = tx.send(Event::Job(JobEvent::Failed { id, error: e.to_string() }));
393:                 }
394:             }
395:         });
396:     }
