398:     /// Native terminal at this folder (Linux/macOS).
399:     pub fn open_terminal(&self, loc: &Location) {
400:         let Some(p) = self.registry.get(&loc.fs).and_then(|v| v.real_path(&loc.path)) else { return };
401:         let dir = if p.is_dir() { p } else { p.parent().map(|x| x.to_path_buf()).unwrap_or(p) };
402:         #[cfg(not(target_arch = "wasm32"))]
403:         {
404:             for (cmd, args) in [("x-terminal-emulator", vec![]), ("gnome-terminal", vec!["--working-directory".to_string(), dir.to_string_lossy().to_string()]), ("konsole", vec!["--workdir".to_string(), dir.to_string_lossy().to_string()]), ("xfce4-terminal", vec!["--working-directory".to_string(), dir.to_string_lossy().to_string()])] {
405:                 let mut c = std::process::Command::new(cmd);
406:                 if args.is_empty() {
407:                     c.current_dir(&dir);
408:                 } else {
409:                     c.args(&args);
410:                 }
411:                 if c.spawn().is_ok() {
412:                     return;
413:                 }
414:             }
415:         }
416:         #[cfg(target_arch = "wasm32")]
417:         let _ = dir;
418:     }
