480:     /// Connect to a network location (smb://, sftp://, dav://, mtp://) through GVfs — real on Linux.
481:     pub fn connect_server(&self, url: &str) {
482:         let (tx, url) = (self.tx.clone(), url.to_string());
483:         #[cfg(not(target_arch = "wasm32"))]
484:         if !self.demo {
485:             spawn(move || {
486:                 let r = std::process::Command::new("gio").args(["mount", &url]).output();
487:                 let (text, ok) = match r {
488:                     Ok(o) if o.status.success() => (format!("Connected to {}", url), true),
489:                     Ok(o) => (String::from_utf8_lossy(&o.stderr).trim().to_string(), false),
490:                     Err(_) => ("Connecting to servers needs GVfs (gio) on this system".to_string(), false),
491:                 };
492:                 let _ = tx.send(Event::Message { text, ok });
493:             });
494:             return;
495:         }
