84: struct Rng(u32);
85: impl Rng {
86:     fn next(&mut self) -> f32 {
87:         self.0 ^= self.0 << 13;
88:         self.0 ^= self.0 >> 17;
89:         self.0 ^= self.0 << 5;
90:         (self.0 as f32 / u32::MAX as f32) * 2.0 - 1.0
