165: fn wallpapers(a: &Path) {
166:     use image::{imageops, Rgb, RgbImage};
167:     let (w, h) = (1600u32, 1000u32);
168:     let mk = |name: &str, stops: [[f32; 3]; 3], blobs: &[(f32, f32, f32, [f32; 3])]| {
169:         let mut img = RgbImage::new(w, h);
170:         for y in 0..h {
171:             for x in 0..w {
172:                 let (u, v) = (x as f32 / w as f32, y as f32 / h as f32);
173:                 let t = (u * 0.35 + v * 0.65).clamp(0.0, 1.0);
174:                 let (c0, c1, tt) = if t < 0.5 { (stops[0], stops[1], t * 2.0) } else { (stops[1], stops[2], (t - 0.5) * 2.0) };
175:                 let mut c = [0.0f32; 3];
176:                 for k in 0..3 {
177:                     c[k] = c0[k] + (c1[k] - c0[k]) * tt;
178:                 }
179:                 for (bx, by, br, bc) in blobs {
180:                     let d = (((u - bx) * 1.6).powi(2) + (v - by).powi(2)).sqrt() / br;
181:                     let m = (1.0 - d).clamp(0.0, 1.0).powi(2) * 0.8;
182:                     for k in 0..3 {
183:                         c[k] += (bc[k] - c[k]) * m;
184:                     }
185:                 }
186:                 let grain = (((x * 7919 + y * 104729) % 97) as f32 / 97.0 - 0.5) * 2.0;
187:                 img.put_pixel(x, y, Rgb([0, 1, 2].map(|k| ((c[k] + grain * 0.6) as i32).clamp(0, 255) as u8)));
188:             }
189:         }
190:         save_jpg(&img, &a.join(format!("{name}.jpg")), 82);
