195:     mk("wallpaper_meadow", [[28.0, 66.0, 70.0], [70.0, 130.0, 96.0], [196.0, 214.0, 130.0]], &[(0.25, 0.8, 0.55, [226.0, 232.0, 150.0]), (0.85, 0.15, 0.5, [60.0, 150.0, 170.0])]);
