197:     // Cobalt Mist ships with the prototype: downscale it for the wasm bundle and derive the blurred glass backdrop.
198:     let src = std::env::var("WALLPAPER_SRC").unwrap_or("/home/user/playground/smart-shell/assets/wallpaper.jpg".into());
199:     let img = image::open(&src).expect("wallpaper.jpg").to_rgb8();
200:     let big = imageops::resize(&img, 1600, 1000, imageops::FilterType::Lanczos3);
201:     save_jpg(&big, &a.join("wallpaper.jpg"), 80);
202:     let small = imageops::resize(&img, 480, 300, imageops::FilterType::Triangle);
203:     save_jpg(&imageops::blur(&small, 14.0), &a.join("wallpaper_blur.jpg"), 80);
204:     let tsrc = Path::new(&src).parent().unwrap().join("thumbs");
