fn open_default(&self, file_name: &str, real: Option<&Path>) -> Result<String, String> {
    let p = real.ok_or("This item is not on a local disk")?;
    // Executables (AppImage/ELF/script) must run directly — xdg-open on them
    // is the classic "says opening but doesn't" lie and often silently fails.
    let lower = file_name.to_ascii_lowercase();
    let looks_like_program = lower.ends_with(".appimage") || lower.ends_with(".elf") || lower.ends_with(".bin") || lower.ends_with(".run") || p.extension().and_then(|e| e.to_str()).is_some_and(|e| e.eq_ignore_ascii_case("sh"));
    if looks_like_program {
        use std::os::unix::fs::PermissionsExt;
        let exec = std::fs::metadata(p).map(|m| m.permissions().mode() & 0o111 != 0).unwrap_or(false);
        if !exec {
            return Err(format!("“{}” isn’t executable yet. Use Get Info → Make executable & run.", file_name));
        }
        let mut c = Command::new(p);
        c.stdin(Stdio::null());
        c.current_dir(p.parent().unwrap_or(Path::new(".")));
        detach(c).map_err(|e| format!("Couldn’t run “{}” — {}", file_name, e))?;
        return Ok(format!("Running {}", file_name));
    }
    let mut c = if cfg!(target_os = "macos") {
        let mut c = Command::new("open");
        c.arg(p);
        c
    } else if cfg!(windows) {
        let mut c = Command::new("cmd");
        c.args(["/C", "start", ""]).arg(p);
        c
    } else {
        let mut c = Command::new("xdg-open");
        c.arg(p);
        c
    };
    c.stdin(Stdio::null());
    detach(c).map_err(|e| format!("Couldn’t open: {}", e))?;
    Ok(format!("Opening {}", file_name))
}

