/// Real MIME sniff: magic bytes win, then extension, then octet-stream.
/// `header` is the first bytes of the file (may be empty for in-memory fs).
pub fn mime_of_bytes(name: &str, header: &[u8]) -> String {
    if !header.is_empty() {
        if let Some(m) = tree_magic_mini::from_u8(header) {
            return m.to_string();
        }
    }
    mime_of(name)
}

