pub struct AdbDevices;
impl AdbDevices {
    fn query(&self) -> Vec<(String, String, String)> {
        let Ok(out) = run("adb", &["devices", "-l"]) else { return vec![] };
        let mut v = vec![];
        for l in out.lines().skip(1) {
            let parts: Vec<&str> = l.split_whitespace().collect();
            if parts.len() < 2 {
                continue;
            }
            let serial = parts[0].to_string();
            let state = parts[1].to_string();
            if state == "device-list" || serial == "List" {
                continue;
            }
            let model = l.split_whitespace().find_map(|p| p.strip_prefix("model:")).unwrap_or("Android").replace('_', " ");
            v.push((serial, model, state));
        }
        v
    }
}
impl DeviceProvider for AdbDevices {
    fn list(&self) -> Vec<Device> {
        self.query()
            .into_iter()
            .map(|(serial, model, state)| {
                let authorized = state == "device";
                let detail = match state.as_str() {
                    "device" => "Android · ADB".into(),
                    "unauthorized" => "Authorization required — tap Allow USB debugging on the phone".into(),
                    "offline" => "Offline — reconnect the phone".into(),
                    other => format!("Android · ADB ({})", other),
                };
                let battery = if authorized {
                    run("adb", &["-s", &serial, "shell", "dumpsys battery | grep level"]).ok().and_then(|s| s.split(':').nth(1).and_then(|n| n.trim().parse().ok()))
                } else {
                    None
                };
                Device { id: format!("adb:{}", serial), name: model, kind: DeviceKind::Phone, detail, mounted: authorized, loc: if authorized { Some(Location::new(format!("adb:{}", serial), "/sdcard")) } else { None }, total: 0, free: 0, fs_type: "adb".into(), can_unmount: false, can_eject: false, battery }
            })
            .collect()
    }

