    /// MTP/GVfs phones: mounted endpoints appear under the runtime gvfs dir.
    pub struct MtpDevices;
    impl MtpDevices {
        fn mounts() -> Vec<(String, String)> {
            let mut out = Vec::new();
            let uid = std::env::var("XDG_RUNTIME_DIR").unwrap_or_else(|_|
                dirs::runtime_dir().map(|p| p.to_string_lossy().to_string()).unwrap_or_default());
            let gvfs = std::path::Path::new(&uid).join("gvfs");
            if let Ok(rd) = std::fs::read_dir(&gvfs) {
                for e in rd.flatten() {
                    let p = e.path();
                    let n = p.file_name().map(|s| s.to_string_lossy().to_string()).unwrap_or_default();
                    if n.starts_with("mtp") {
                        out.push((p.to_string_lossy().to_string(), n));
                    }
                }
            }
            out
        }
    }
    impl DeviceProvider for MtpDevices {
        fn list(&self) -> Vec<Device> {
            Self::mounts()
                .into_iter()
                .map(|(mount, label)| Device {
                    id: format!("mtp:{}", label),
                    name: label.replace("mtp:", ""),
                    kind: DeviceKind::Phone,
                    detail: "Android · MTP (GVfs)".into(),
                    mounted: true,
                    loc: Some(crate::local::path_to_loc(std::path::Path::new(&mount))),
                    total: 0,
                    free: 0,
                    fs_type: "mtp".into(),
                    can_unmount: false,
                    can_eject: false,
                    battery: None,
                })
                .collect()
        }
        fn mount(&self, _id: &str) -> Result<Mounted, String> {
            Err("MTP mounts are handled by GVfs automatically — look under Locations".into())
        }
        fn unmount(&self, _id: &str) -> Result<(), String> {
            run("gio", &["mount", "-u", "mtp://"]).map(|_| ())
        }
        fn owns(&self, id: &str) -> bool {
            id.starts_with("mtp:")
        }
    }

    pub fn diagnostics() -> String {
        let mut s = String::from("Smart Files diagnostics\n");
        for (cmd, args) in [
            ("lsusb", vec![]),
            ("lsblk", vec!["-o", "NAME,MODEL,SIZE,FSTYPE,MOUNTPOINT"]),
            ("adb", vec!["devices", "-l"]),
            ("gio", vec!["list"]),
        ] {
            let r = run(cmd, &args).unwrap_or_else(|e| format!("(unavailable: {})", e));
            let head: String = r.lines().take(12).collect::<Vec<_>>().join("\n");
            s.push_str(&format!("\n$ {} {}\n{}\n", cmd, args.join(" "), head));
        }
        s
    }
}

